/**
 * Scene-script DSL v1 — the contract between the agent crew and the engine.
 *
 * Source of truth for both TypeScript types (inferred) and the JSON Schema
 * embedded in model prompts (generated by scripts/gen-json-schema.ts).
 *
 * v1 = DSL v0 (actors, scenes, steps, narration, checks) + `version`,
 * `controls` and `scenes[].beat`. See docs/dsl-changelog.md.
 */
import { z } from "zod";
import { HEX_RE, isPaletteKey } from "./palette";

export const DSL_VERSION = "1.0";

/** Hard limits enforced by the validator (over-limit content is dropped). */
export const LIMITS = {
  maxActors: 24,
  maxScenes: 9,
  maxStepsPerScene: 12,
  maxChecks: 6,
  minSceneDuration: 3,
  maxSceneDuration: 60,
  /** Validator clamps world coordinates to these bounds. */
  world: { xMax: 40, yMin: -5, yMax: 30, zMax: 30 },
} as const;

// ---------------------------------------------------------------------------
// Primitives
// ---------------------------------------------------------------------------

export const ColorSchema = z
  .string()
  .refine((v) => isPaletteKey(v) || HEX_RE.test(v), {
    message: "color must be a palette key (a b c d e f g o) or #rrggbb",
  })
  .describe("Palette key a|b|c|d|e|f|g|o or literal #rrggbb");

export const Vec3Schema = z.object({
  x: z.number(),
  y: z.number(),
  z: z.number(),
});
export type Vec3 = z.infer<typeof Vec3Schema>;

export const ActorIdSchema = z
  .string()
  .min(1)
  .max(24)
  .regex(/^[a-z0-9][a-z0-9_-]*$/, "actor ids are lower-case [a-z0-9_-]");

// ---------------------------------------------------------------------------
// Actors
// ---------------------------------------------------------------------------

export const ActorSchema = z.object({
  id: ActorIdSchema,
  kind: z.enum(["prop", "text"]).default("prop"),
  /** Prop name from the catalogue; required when kind="prop". */
  prop: z.string().optional(),
  label: z.string().max(80).default(""),
  color: ColorSchema.default("f"),
  x: z.number().default(0),
  y: z.number().default(0),
  z: z.number().default(0),
  /** Height in world units. */
  size: z.number().positive().max(30).default(2),
  hidden: z.boolean().default(false),
});
export type Actor = z.infer<typeof ActorSchema>;

// ---------------------------------------------------------------------------
// Steps — discriminated on `action`
// ---------------------------------------------------------------------------

const stepBase = {
  t: z.number().min(0).describe("Seconds from scene start"),
  dur: z.number().min(0).max(60).default(1),
};

export const StepSchema = z.discriminatedUnion("action", [
  z.object({ action: z.literal("show"), actor: ActorIdSchema, ...stepBase }),
  z.object({ action: z.literal("hide"), actor: ActorIdSchema, ...stepBase }),
  z.object({
    action: z.literal("move"),
    actor: ActorIdSchema,
    to: Vec3Schema,
    ...stepBase,
  }),
  z.object({
    action: z.literal("grow"),
    actor: ActorIdSchema,
    /** Target size (height in world units). */
    to: z.number().positive().max(30),
    ...stepBase,
  }),
  z.object({
    action: z.literal("pulse"),
    actor: ActorIdSchema,
    scale: z.number().min(1).max(3).default(1.15),
    times: z.number().int().min(1).max(12).default(3),
    ...stepBase,
  }),
  z.object({
    action: z.literal("rotate"),
    actor: ActorIdSchema,
    axis: z.enum(["x", "y", "z"]).default("y"),
    /** Full revolutions over `dur`; negative = reverse. Multiplied by a bound `speed` control. */
    turns: z.number().min(-50).max(50).default(1),
    ...stepBase,
  }),
  z.object({ action: z.literal("highlight"), actor: ActorIdSchema, ...stepBase }),
  z.object({
    action: z.literal("shake"),
    actor: ActorIdSchema,
    amplitude: z.number().min(0).max(5).default(0.3),
    ...stepBase,
  }),
  z.object({
    action: z.literal("label"),
    actor: ActorIdSchema,
    text: z.string().max(80),
    ...stepBase,
  }),
  z.object({
    action: z.literal("count"),
    actor: ActorIdSchema,
    from: z.number(),
    to: z.number(),
    prefix: z.string().max(20).default(""),
    suffix: z.string().max(20).default(""),
    ...stepBase,
  }),
  z.object({
    action: z.literal("color"),
    actor: ActorIdSchema,
    to: ColorSchema,
    ...stepBase,
  }),
  z.object({
    action: z.literal("flow"),
    from: ActorIdSchema,
    to: ActorIdSchema,
    /** Particles over the whole flow; multiplied by a bound `count` control. */
    count: z.number().int().min(1).max(60).default(8),
    shape: z.enum(["sphere", "cube", "drop"]).default("sphere"),
    color: ColorSchema.default("c"),
    ...stepBase,
  }),
  z.object({
    action: z.literal("camera"),
    to: Vec3Schema,
    look: Vec3Schema,
    ...stepBase,
  }),
]);
export type Step = z.infer<typeof StepSchema>;
export type StepAction = Step["action"];

export const STEP_ACTIONS = [
  "show",
  "hide",
  "move",
  "grow",
  "pulse",
  "rotate",
  "highlight",
  "shake",
  "label",
  "count",
  "color",
  "flow",
  "camera",
] as const;

// ---------------------------------------------------------------------------
// Scenes
// ---------------------------------------------------------------------------

export const NarrationSchema = z.object({
  t: z.number().min(0),
  text: z.string().min(1).max(400),
});
export type Narration = z.infer<typeof NarrationSchema>;

export const SceneSchema = z.object({
  title: z.string().min(1).max(120),
  duration: z
    .number()
    .min(LIMITS.minSceneDuration)
    .max(LIMITS.maxSceneDuration),
  backdrop: z.enum(["lab", "nature", "space", "plain"]).default("lab"),
  /** One sentence: what the learner must SEE happen. Written by the Director,
   *  consumed by the Inspector as the scene's acceptance criterion. */
  beat: z.string().max(300).default(""),
  narration: z.array(NarrationSchema).max(6).default([]),
  keyFact: z.string().max(300).default(""),
  steps: z.array(StepSchema).max(LIMITS.maxStepsPerScene).default([]),
});
export type Scene = z.infer<typeof SceneSchema>;

// ---------------------------------------------------------------------------
// Controls (new in v1) — learner-facing sliders
// ---------------------------------------------------------------------------

export const ControlBindSchema = z.object({
  actor: ActorIdSchema,
  property: z.enum(["speed", "scale", "count", "visible"]),
});
export type ControlBind = z.infer<typeof ControlBindSchema>;

export const ControlSchema = z
  .object({
    id: z.string().min(1).max(24),
    label: z.string().min(1).max(60),
    min: z.number(),
    max: z.number(),
    default: z.number(),
    binds: z.array(ControlBindSchema).min(1).max(6),
  })
  .refine((c) => c.min < c.max, { message: "min must be < max" })
  .refine((c) => c.default >= c.min && c.default <= c.max, {
    message: "default must be within [min, max]",
  });
export type Control = z.infer<typeof ControlSchema>;

// ---------------------------------------------------------------------------
// Checks
// ---------------------------------------------------------------------------

export const CheckSchema = z
  .object({
    question: z.string().min(1).max(300),
    options: z.array(z.string().min(1).max(200)).min(2).max(5),
    /** Zero-based index into options. */
    answer: z.number().int().min(0),
    explain: z.string().max(400).default(""),
  })
  .refine((c) => c.answer < c.options.length, {
    message: "answer must index into options",
  });
export type Check = z.infer<typeof CheckSchema>;

// ---------------------------------------------------------------------------
// Script
// ---------------------------------------------------------------------------

export const ScriptSchema = z.object({
  version: z.literal(DSL_VERSION),
  title: z.string().min(1).max(160),
  language: z.string().min(2).max(12),
  camera: z.object({
    x: z.number(),
    y: z.number(),
    z: z.number(),
    look: Vec3Schema,
  }),
  actors: z.array(ActorSchema).max(LIMITS.maxActors),
  scenes: z.array(SceneSchema).min(1).max(LIMITS.maxScenes),
  controls: z.array(ControlSchema).max(6).default([]),
  checks: z.array(CheckSchema).max(LIMITS.maxChecks).default([]),
});
export type Script = z.infer<typeof ScriptSchema>;
/** Authoring type: fields with defaults are optional. */
export type ScriptInput = z.input<typeof ScriptSchema>;
